public class Main {
    public static void main(String[] args) {
        String h = "{h}";
        String t = "{t}";
        String a = h + t;
        String b = h + t;
        String c = "{h}{t}";
        System.out.println("两条拼出来的，是同一条吗：" + (a == b));
        System.out.println("拼出来的和写出来的，是同一条吗：" + (a == c));
        System.out.println("可里面的字一模一样：" + a.equals(c));
    }
}
